  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→
 12→function generateId() {
 13→  return crypto.randomUUID();
 14→}
 15→
 16→export function AgentProvider({
 17→  children,
 18→  refreshTables,
 19→}: {
 20→  children: ReactNode;
 21→  refreshTables: () => Promise<void>;
 22→}) {
 23→  const userSessionId = useSessionId();
 24→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 25→  const [isStreaming, setIsStreaming] = useState(false);
 26→  const abortRef = useRef<AbortController | null>(null);
 27→  const textBufferRef = useRef('');
 28→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 29→  const assistantIdRef = useRef('');
 30→  const segmentsRef = useRef<ContentSegment[]>([]);
 31→  const currentTextRef = useRef('');
 32→  const sessionIdRef = useRef<string | null>(null);
 33→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 34→
 35→  const flushText = useCallback(() => {
 36→    const text = textBufferRef.current;
 37→    if (!text) return;
 38→    const id = assistantIdRef.current;
 39→    currentTextRef.current += text;
 40→    setMessages((prev) =>
 41→      prev.map((m) =>
 42→        m.id === id ? { ...m, content: m.content + text } : m
 43→      )
 44→    );
 45→    textBufferRef.current = '';
 46→  }, []);
 47→
 48→  const sendMessage = useCallback(
 49→    async (text: string) => {
 50→      if (isStreaming) return;
 51→
 52→      const userMsg: ChatMessage = {
 53→        id: generateId(),
 54→        role: 'user',
 55→        content: text,
 56→      };
 57→
 58→      const assistantId = generateId();
 59→      assistantIdRef.current = assistantId;
 60→      const assistantMsg: ChatMessage = {
 61→        id: assistantId,
 62→        role: 'assistant',
 63→        content: '',
 64→        toolCalls: [],
 65→        isStreaming: true,
 66→      };
 67→
 68→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 69→      setIsStreaming(true);
 70→      textBufferRef.current = '';
 71→      segmentsRef.current = [];
 72→      currentTextRef.current = '';
 73→
 74→      // If there's pending history from a delete, start a new Langfuse session with that context
 75→      const pendingHistory = pendingHistoryRef.current;
 76→      pendingHistoryRef.current = null;
 77→      const langfuseSessionId = pendingHistory ? crypto.randomUUID() : null;
 78→
 79→      const controller = new AbortController();
 80→      abortRef.current = controller;
 81→
 82→      await runAgentLoop(
 83→        text,
 84→        sessionIdRef.current,
 85→        langfuseSessionId,
 86→        pendingHistory,
 87→        {
 88→          onTextChunk: (chunk) => {
 89→            textBufferRef.current += chunk;
 90→            if (!flushTimerRef.current) {
 91→              flushTimerRef.current = setTimeout(() => {
 92→                flushText();
 93→                flushTimerRef.current = null;
 94→              }, 50);
 95→            }
 96→          },
 97→          onThinkingDone: () => {
 98→            // Extended thinking just ended and a text block is starting.
 99→            // Create a thinking segment from accumulated thinking text.
100→            if (flushTimerRef.current) {
101→              clearTimeout(flushTimerRef.current);
102→              flushTimerRef.current = null;
103→            }
104→            flushText();
105→            if (currentTextRef.current.trim()) {
106→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
107→              currentTextRef.current = '';
108→            }
109→            setMessages((prev) =>
110→              prev.map((m) =>
111→                m.id === assistantId
112→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
113→                  : m
114→              )
115→            );
116→          },
117→          onToolCall: (pending: ToolCallResult) => {
118→            if (flushTimerRef.current) {
119→              clearTimeout(flushTimerRef.current);
120→              flushTimerRef.current = null;
121→            }
122→            flushText();
123→            if (currentTextRef.current.trim()) {
124→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
125→              currentTextRef.current = '';
126→            }
127→            // Add a pending tool segment so the input is shown immediately
128→            segmentsRef.current.push({
129→              type: 'tool',
130→              toolResult: pending,
131→            });
132→            setMessages((prev) =>
133→              prev.map((m) =>
134→                m.id === assistantId
135→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
136→                  : m
137→              )
138→            );
139→          },
140→          onToolResult: (result: ToolCallResult) => {
141→            // Merge result into pending tool segment (keep input info, add output)
142→            const pendingIdx = segmentsRef.current.findIndex(
143→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
144→            );
145→            if (pendingIdx !== -1) {
146→              const pending = segmentsRef.current[pendingIdx].toolResult!;
147→              segmentsRef.current[pendingIdx] = {
148→                type: 'tool',
149→                toolResult: {
150→                  ...pending,
151→                  ...result,
152→                  sql: result.sql || pending.sql,
153→                  toolName: result.toolName || pending.toolName,
154→                  command: result.command || pending.command,
155→                  toolInput: result.toolInput || pending.toolInput,
156→                },
157→              };
158→            } else {
159→              segmentsRef.current.push({ type: 'tool', toolResult: result });
160→            }
161→            setMessages((prev) =>
162→              prev.map((m) =>
163→                m.id === assistantId
164→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
165→                  : m
166→              )
167→            );
168→            refreshTables();
169→          },
170→          onSubagentStart: (data) => {
171→            if (flushTimerRef.current) {
172→              clearTimeout(flushTimerRef.current);
173→              flushTimerRef.current = null;
174→            }
175→            flushText();
176→            if (currentTextRef.current.trim()) {
177→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
178→              currentTextRef.current = '';
179→            }
180→            segmentsRef.current.push({
181→              type: 'subagent_start',
182→              subagentId: data.id,
183→              subagentName: data.name,
184→              text: data.prompt,
185→            });
186→            setMessages((prev) =>
187→              prev.map((m) =>
188→                m.id === assistantId
189→                  ? { ...m, segments: [...segmentsRef.current] }
190→                  : m
191→              )
192→            );
193→          },
194→          onSubagentEnd: (data) => {
195→            segmentsRef.current.push({
196→              type: 'subagent_end',
197→              subagentId: data.id,
198→              subagentName: data.name,
199→              chart_spec: data.chart_spec,
200→              text: data.result,
201→            });
202→            setMessages((prev) =>
203→              prev.map((m) =>
204→                m.id === assistantId
205→                  ? { ...m, segments: [...segmentsRef.current] }
206→                  : m
207→              )
208→            );
209→          },
210→          onDone: (newSessionId) => {
211→            if (newSessionId) sessionIdRef.current = newSessionId;
212→            if (flushTimerRef.current) {
213→              clearTimeout(flushTimerRef.current);
214→              flushTimerRef.current = null;
215→            }
216→            flushText();
217→            if (currentTextRef.current.trim()) {
218→              segmentsRef.current.push({
219→                type: 'answer',
220→                text: currentTextRef.current,
221→              });
222→              currentTextRef.current = '';
223→            }
224→            setMessages((prev) =>
225→              prev.map((m) =>
226→                m.id === assistantId
227→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
228→                  : m
229→              )
230→            );
231→            setIsStreaming(false);
232→            abortRef.current = null;
233→          },
234→          onError: (error) => {
235→            if (flushTimerRef.current) {
236→              clearTimeout(flushTimerRef.current);
237→              flushTimerRef.current = null;
238→            }
239→            flushText();
240→            setMessages((prev) =>
241→              prev.map((m) =>
242→                m.id === assistantId
243→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
244→                  : m
245→              )
246→            );
247→            setIsStreaming(false);
248→            abortRef.current = null;
249→          },
250→          onUserQuestion: (data) => {
251→            if (flushTimerRef.current) {
252→              clearTimeout(flushTimerRef.current);
253→              flushTimerRef.current = null;
254→            }
255→            flushText();
256→            if (currentTextRef.current.trim()) {
257→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
258→              currentTextRef.current = '';
259→            }
260→            segmentsRef.current.push({
261→              type: 'user_question',
262→              questionData: data,
263→            });
264→            setMessages((prev) =>
265→              prev.map((m) =>
266→                m.id === assistantId
267→                  ? { ...m, segments: [...segmentsRef.current] }
268→                  : m
269→              )
270→            );
271→          },
272→        },
273→        controller.signal,
274→        userSessionId,
275→      );
276→    },
277→    [isStreaming, flushText, refreshTables, userSessionId]
278→  );
279→
280→  const editMessage = useCallback(
281→    async (messageIndex: number, newContent: string) => {
282→      if (isStreaming) return;
283→
284→      // Build conversation history from messages before the edit point
285→      const conversationHistory: { role: string; content: string }[] = [];
286→      for (let i = 0; i < messageIndex; i++) {
287→        const msg = messages[i];
288→        if (msg.role === 'user' || msg.role === 'assistant') {
289→          conversationHistory.push({ role: msg.role, content: msg.content });
290→        }
291→      }
292→
293→      const assistantId = generateId();
294→      assistantIdRef.current = assistantId;
295→
296→      const userMsg: ChatMessage = {
297→        id: generateId(),
298→        role: 'user',
299→        content: newContent,
300→      };
301→      const assistantMsg: ChatMessage = {
302→        id: assistantId,
303→        role: 'assistant',
304→        content: '',
305→        toolCalls: [],
306→        isStreaming: true,
307→      };
308→
309→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
310→      setIsStreaming(true);
311→      textBufferRef.current = '';
312→      segmentsRef.current = [];
313→      currentTextRef.current = '';
314→
315→      const controller = new AbortController();
316→      abortRef.current = controller;
317→
318→      await runAgentEditLoop(
319→        newContent,
320→        conversationHistory,
321→        crypto.randomUUID(),
322→        {
323→          onTextChunk: (chunk) => {
324→            textBufferRef.current += chunk;
325→            if (!flushTimerRef.current) {
326→              flushTimerRef.current = setTimeout(() => {
327→                flushText();
328→                flushTimerRef.current = null;
329→              }, 50);
330→            }
331→          },
332→          onThinkingDone: () => {
333→            if (flushTimerRef.current) {
334→              clearTimeout(flushTimerRef.current);
335→              flushTimerRef.current = null;
336→            }
337→            flushText();
338→            if (currentTextRef.current.trim()) {
339→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
340→              currentTextRef.current = '';
341→            }
342→            setMessages((prev) =>
343→              prev.map((m) =>
344→                m.id === assistantId
345→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
346→                  : m
347→              )
348→            );
349→          },
350→          onToolCall: (pending: ToolCallResult) => {
351→            if (flushTimerRef.current) {
352→              clearTimeout(flushTimerRef.current);
353→              flushTimerRef.current = null;
354→            }
355→            flushText();
356→            if (currentTextRef.current.trim()) {
357→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
358→              currentTextRef.current = '';
359→            }
360→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
361→            setMessages((prev) =>
362→              prev.map((m) =>
363→                m.id === assistantId
364→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
365→                  : m
366→              )
367→            );
368→          },
369→          onToolResult: (result: ToolCallResult) => {
370→            const pendingIdx = segmentsRef.current.findIndex(
371→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
372→            );
373→            if (pendingIdx !== -1) {
374→              const pending = segmentsRef.current[pendingIdx].toolResult!;
375→              segmentsRef.current[pendingIdx] = {
376→                type: 'tool',
377→                toolResult: {
378→                  ...pending,
379→                  ...result,
380→                  sql: result.sql || pending.sql,
381→                  toolName: result.toolName || pending.toolName,
382→                  command: result.command || pending.command,
383→                  toolInput: result.toolInput || pending.toolInput,
384→                },
385→              };
386→            } else {
387→              segmentsRef.current.push({ type: 'tool', toolResult: result });
388→            }
389→            setMessages((prev) =>
390→              prev.map((m) =>
391→                m.id === assistantId
392→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
393→                  : m
394→              )
395→            );
396→            refreshTables();
397→          },
398→          onSubagentStart: (data) => {
399→            if (flushTimerRef.current) {
400→              clearTimeout(flushTimerRef.current);
401→              flushTimerRef.current = null;
402→            }
403→            flushText();
404→            if (currentTextRef.current.trim()) {
405→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
406→              currentTextRef.current = '';
407→            }
408→            segmentsRef.current.push({
409→              type: 'subagent_start',
410→              subagentId: data.id,
411→              subagentName: data.name,
412→              text: data.prompt,
413→            });
414→            setMessages((prev) =>
415→              prev.map((m) =>
416→                m.id === assistantId
417→                  ? { ...m, segments: [...segmentsRef.current] }
418→                  : m
419→              )
420→            );
421→          },
422→          onSubagentEnd: (data) => {
423→            segmentsRef.current.push({
424→              type: 'subagent_end',
425→              subagentId: data.id,
426→              subagentName: data.name,
427→              chart_spec: data.chart_spec,
428→              text: data.result,
429→            });
430→            setMessages((prev) =>
431→              prev.map((m) =>
432→                m.id === assistantId
433→                  ? { ...m, segments: [...segmentsRef.current] }
434→                  : m
435→              )
436→            );
437→          },
438→          onDone: (newSessionId) => {
439→            if (newSessionId) sessionIdRef.current = newSessionId;
440→            if (flushTimerRef.current) {
441→              clearTimeout(flushTimerRef.current);
442→              flushTimerRef.current = null;
443→            }
444→            flushText();
445→            if (currentTextRef.current.trim()) {
446→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
447→              currentTextRef.current = '';
448→            }
449→            setMessages((prev) =>
450→              prev.map((m) =>
451→                m.id === assistantId
452→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
453→                  : m
454→              )
455→            );
456→            setIsStreaming(false);
457→            abortRef.current = null;
458→          },
459→          onError: (error) => {
460→            if (flushTimerRef.current) {
461→              clearTimeout(flushTimerRef.current);
462→              flushTimerRef.current = null;
463→            }
464→            flushText();
465→            setMessages((prev) =>
466→              prev.map((m) =>
467→                m.id === assistantId
468→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
469→                  : m
470→              )
471→            );
472→            setIsStreaming(false);
473→            abortRef.current = null;
474→          },
475→          onUserQuestion: (data) => {
476→            if (flushTimerRef.current) {
477→              clearTimeout(flushTimerRef.current);
478→              flushTimerRef.current = null;
479→            }
480→            flushText();
481→            if (currentTextRef.current.trim()) {
482→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
483→              currentTextRef.current = '';
484→            }
485→            segmentsRef.current.push({
486→              type: 'user_question',
487→              questionData: data,
488→            });
489→            setMessages((prev) =>
490→              prev.map((m) =>
491→                m.id === assistantId
492→                  ? { ...m, segments: [...segmentsRef.current] }
493→                  : m
494→              )
495→            );
496→          },
497→        },
498→        controller.signal,
499→        userSessionId,
500→      );
501→    },
502→    [isStreaming, messages, flushText, refreshTables, userSessionId]
503→  );
504→
505→  const deleteMessage = useCallback(
506→    (messageIndex: number) => {
507→      if (isStreaming) return;
508→
509→      // Store remaining messages as history for Langfuse context on next send
510→      setMessages((prev) => {
511→        const remaining = prev.slice(0, messageIndex);
512→        pendingHistoryRef.current = remaining
513→          .filter((m) => m.role === 'user' || m.role === 'assistant')
514→          .map((m) => ({ role: m.role, content: m.content }));
515→        return remaining;
516→      });
517→
518→      // Clear session so next message starts fresh
519→      sessionIdRef.current = null;
520→    },
521→    [isStreaming]
522→  );
523→
524→  const respondToQuestion = useCallback(
525→    async (questionId: string, answers: string[], freeText?: string) => {
526→      // Update the segment to show the user's answer
527→      const segIdx = segmentsRef.current.findIndex(
528→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
529→      );
530→      if (segIdx !== -1) {
531→        segmentsRef.current[segIdx] = {
532→          ...segmentsRef.current[segIdx],
533→          userAnswer: answers,
534→        };
535→        setMessages((prev) =>
536→          prev.map((m) =>
537→            m.id === assistantIdRef.current
538→              ? { ...m, segments: [...segmentsRef.current] }
539→              : m
540→          )
541→        );
542→      }
543→
544→      // POST to backend
545→      try {
546→        await fetch('/api/chat/respond', {
547→          method: 'POST',
548→          headers: {
549→            'Content-Type': 'application/json',
550→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
551→          },
552→          body: JSON.stringify({
553→            question_id: questionId,
554→            answers,
555→            free_text: freeText || null,
556→          }),
557→        });
558→      } catch (e) {
559→        console.error('Failed to respond to question:', e);
560→      }
561→    },
562→    [userSessionId]
563→  );
564→
565→  const clearMessages = useCallback(() => {
566→    if (abortRef.current) {
567→      abortRef.current.abort();
568→    }
569→    setMessages([]);
570→    setIsStreaming(false);
571→    sessionIdRef.current = null;
572→    pendingHistoryRef.current = null;
573→  }, []);
574→
575→  return (
576→    <AgentContext.Provider
577→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
578→    >
579→      {children}
580→    </AgentContext.Provider>
581→  );
582→}
